def nmse(y,p): return np.mean((y-p)**2)/np.var(y)
bases={'1':np.ones_like(t),'t':t,'t2':t**2,'t3':t**3,'et':np.exp(-t),'e05':np.exp(-0.5*t),'sqrt':np.sqrt(t),'log':np.log(t),'1/t':1/t,'sin':np.sin(t),'cos':np.cos(t),'t^1.5':t**1.5}
import itertools
def test(c0n,c1n):
    cols=[A**2,A**3]
    cols+= [bases[n] for n in c0n]
    cols+= [bases[n]*A for n in c1n]
    X=np.array(cols).T
    c,*_=np.linalg.lstsq(X,dA_dt,rcond=None)
    return nmse(dA_dt,X@c),c
res=[]
keys=list(bases)
for c0 in itertools.combinations(keys,2):
    for c1 in itertools.combinations(keys,2):
        e,_=test(c0,c1); res.append((e,c0,c1))
res.sort(key=lambda x:x[0])
for r in res[:8]: print(r)

def nmse(y,p): return np.mean((y-p)**2)/np.var(y)
tb={'1':np.ones_like(t),'t':t,'t2':t**2,'t3':t**3,'et':np.exp(-t),'e05':np.exp(-0.5*t),'sqrt':np.sqrt(t),'log':np.log(t),'1/t':1/t,'sin':np.sin(t),'cos':np.cos(t),'1/(1+t)':1/(1+t),'exp(t/10)':np.exp(t/10)}
cols=[];nm=[]
for j in range(4):
  for k,v in tb.items():
    cols.append(v*A**j); nm.append(f"{k}*A^{j}")
X=np.array(cols).T
c,*_=np.linalg.lstsq(X,dA_dt,rcond=None)
