# backward elimination to sparsest
keep=list(range(X.shape[1]))
while len(keep)>1:
    best=None
    for k in keep:
        kk=[q for q in keep if q!=k]
        cc,*_=np.linalg.lstsq(X[:,kk],dA_dt,rcond=None)
        e=nmse(dA_dt,X[:,kk]@cc)
        if best is None or e<best[0]: best=(e,k)
